def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find contiguous non-background runs on the four borders.
    runs = []
    def add_runs(cells, side, axis):
        i = 0
        while i < len(cells):
            color = cells[i]
            if color == bg:
                i += 1
                continue
            j = i + 1
            while j < len(cells) and cells[j] == color:
                j += 1
            runs.append({
                "side": side, "axis": axis, "color": color,
                "start": i, "end": j - 1
            })
            i = j

    add_runs(grid[0], "top", "h")
    add_runs(grid[h - 1], "bottom", "h")
    add_runs([grid[r][0] for r in range(h)], "left", "v")
    add_runs([grid[r][w - 1] for r in range(h)], "right", "v")

    pairs = []
    for a in runs:
        for b in runs:
            if a["color"] != b["color"] or a["axis"] != b["axis"]:
                continue
            if (a["side"], b["side"]) not in (("top", "bottom"), ("bottom", "top"),
                                               ("left", "right"), ("right", "left")):
                continue
            if a["side"] in ("bottom", "right"):
                continue
            pairs.append((a, b))

    if not pairs:
        return [row[:] for row in grid]

    def axis_coord(r, c, axis):
        return c if axis == "h" else r

    best = None
    best_score = None
    for a, b in pairs:
        bar = a["color"]
        markers = [(r, c) for r in range(h) for c in range(w)
                   if grid[r][c] != bg and grid[r][c] != bar]
        ca = sum(a["start"] <= axis_coord(r, c, a["axis"]) <= a["end"]
                 for r, c in markers)
        cb = sum(b["start"] <= axis_coord(r, c, b["axis"]) <= b["end"]
                 for r, c in markers)
        score = (max(ca, cb), min(a["end"] - a["start"], b["end"] - b["start"]))
        if best_score is None or score > best_score:
            best, best_score = (a, b, markers), score

    a, b, markers = best
    bar = a["color"]
    marker_colors = {grid[r][c] for r, c in markers}
    marker = next(iter(marker_colors)) if marker_colors else None

    # Use marker positions aligned with one of the border runs to define offsets.
    ca = sum(a["start"] <= axis_coord(r, c, a["axis"]) <= a["end"]
             for r, c in markers)
    cb = sum(b["start"] <= axis_coord(r, c, b["axis"]) <= b["end"]
             for r, c in markers)
    source, target = (a, b) if ca >= cb else (b, a)
    offsets = sorted({
        axis_coord(r, c, source["axis"]) - source["start"]
        for r, c in markers
        if source["start"] <= axis_coord(r, c, source["axis"]) <= source["end"]
    })
    if not offsets:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    marker_cells = set(markers)
    for r, c in markers:
        out[r][c] = 4

    def border_cell(run, pos):
        if run["side"] == "top":
            return (0, pos)
        if run["side"] == "bottom":
            return (h - 1, pos)
        if run["side"] == "left":
            return (pos, 0)
        return (pos, w - 1)

    def inward_step(side):
        return {"top": (1, 0), "bottom": (-1, 0),
                "left": (0, 1), "right": (0, -1)}[side]

    for run in (source, target):
        for off in offsets:
            pos = run["start"] + off
            if pos > run["end"]:
                continue
            r, c = border_cell(run, pos)
            dr, dc = inward_step(run["side"])
            r += dr
            c += dc
            while 0 <= r < h and 0 <= c < w:
                if grid[r][c] == bar:
                    break
                if (r, c) in marker_cells:
                    out[r][c] = 4
                    break
                out[r][c] = marker
                r += dr
                c += dc

    return out
